    lines.add(new Ruling(100f, 10f, 50f, 0f));
    // Line B: x=40 to 90 (width 50). Overlaps with Line A between 40 and 60.
    lines.add(new Ruling(100f, 40f, 50f, 0f));

    // Scenario 2: Collinear lines separated by a gap smaller than or equal to expandAmount
    // Two lines at y=200.
    // Line C: x=10 to 30 (width 20)
    lines.add(new Ruling(200f, 10f, 20f, 0f));
    // Line D: x=35 to 55 (width 20). Gap is 5 (30 to 35).
    lines.add(new Ruling(200f, 35f, 20f, 0f));

    // Scenario 3: Collinear lines separated by a gap larger than expandAmount
    // Two lines at y=300.
    // Line E: x=10 to 20 (width 10)
    lines.add(new Ruling(300f, 10f, 10f, 0f));
    // Line F: x=30 to 40 (width 10). Gap is 10 (20 to 30).
    lines.add(new Ruling(300f, 30f, 10f, 0f));

    // Scenario 4: Zero-length line (should be discarded)
    // Line G: y=400, x=10 to 10 (width 0)
    lines.add(new Ruling(400f, 10f, 0f, 0f));

    // Set expandAmount to 5.
    // This should allow Scenario 2 to merge, but not Scenario 3.
    int expandAmount = 5;

    // Invoke the method under test
    List<Ruling> collapsedLines = Ruling.collapseOrientedRulings(lines, expandAmount);

    // Validate the results
    
    // Expected size:
    // Scenario 1 (Overlap): Merges into 1 line.
    // Scenario 2 (Gap <= expand): Merges into 1 line.
    // Scenario 3 (Gap > expand): Remains 2 lines.
    // Scenario 4 (Zero len): Removed.
    // Total = 4 lines.
    org.junit.Assert.assertEquals("Should return 4 collapsed rulings", 4, collapsedLines.size());

    // Verify Scenario 1: Merged line from 10 to 90 at y=100
    Ruling r1 = collapsedLines.get(0);
    org.junit.Assert.assertEquals("Position (Y) should be 100", 100f, r1.getPosition(), 0.001f);
    org.junit.Assert.assertEquals("Start (X) should be 10", 10f, r1.getStart(), 0.001f);
    org.junit.Assert.assertEquals("End (X) should be 90", 90f, r1.getEnd(), 0.001f);

